// 公尺座標（x 東、y 北、z 高程）→ three.js（y 朝上、北 = −z）
const toV = (x, y, z) => new THREE.Vector3(x - S.W / 2, (z - S.zmid) * EXAG, S.H / 2 - y);
const fromV = (v) => ({ x: v.x + S.W / 2, y: S.H / 2 - v.z });

function heightAt(x, y) {
  const { w, h, data } = S.terr;
  const fi = Math.min(Math.max((x / S.W) * (w - 1), 0), w - 1);
  const fj = Math.min(Math.max((y / S.H) * (h - 1), 0), h - 1);
  const i0 = Math.floor(fi), j0 = Math.floor(fj), i1 = Math.min(i0 + 1, w - 1), j1 = Math.min(j0 + 1, h - 1);
  const tx = fi - i0, ty = fj - j0, z = (i, j) => data[j * w + i];
  return (z(i0, j0) * (1 - tx) + z(i1, j0) * tx) * (1 - ty) + (z(i0, j1) * (1 - tx) + z(i1, j1) * tx) * ty;
}
const groundV = (x, y, lift = 0) => toV(x, y, heightAt(x, y) + lift / EXAG);
/** 全解析度網格查詢（hazard / slope / rough）。 */
function cellVal(g, x, y) {
  const i = Math.floor(x / S.meta.cell_m), j = Math.floor(y / S.meta.cell_m);
  if (i < 0 || j < 0 || i >= g.w || j >= g.h) return null;
  return g.data[j * g.w + i];
}
const isHazard = (x, y) => { const v = cellVal(S.hazard, x, y); return v === null || v > 127; };
const slopeAt = (x, y) => ((cellVal(S.slope, x, y) ?? 0) / 254) * 45;

// ---------------------------------------------------------------- terrain + layers
let terrainMesh, baseColors;
function buildTerrain() {
  const { w, h, data } = S.terr;
  const geo = new THREE.PlaneGeometry(S.W, S.H, w - 1, h - 1);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position;
  baseColors = new Float32Array(pos.count * 3);
  const lo = new THREE.Color('#5a2a17'), hi = new THREE.Color('#d0915f'), c = new THREE.Color();
  const span = S.meta.z_max - S.meta.z_min || 1;
  for (let r = 0; r < h; r++) {
    for (let col = 0; col < w; col++) {
      const k = r * w + col, z = data[(h - 1 - r) * w + col]; // 資料第 0 列在南
      pos.setY(k, (z - S.zmid) * EXAG);
      // 高程漸層 + 細微雜色，看起來像風化的火星土壤
      const n = Math.abs((Math.sin(col * 12.9898 + r * 78.233) * 43758.5453) % 1);
      c.copy(lo).lerp(hi, (z - S.meta.z_min) / span).offsetHSL(0, 0, (n - 0.5) * 0.03);
      baseColors.set([c.r, c.g, c.b], k * 3);
    }
  }
  geo.computeVertexNormals();
  geo.setAttribute('color', new THREE.BufferAttribute(baseColors.slice(), 3));
  terrainMesh = new THREE.Mesh(geo, new THREE.MeshLambertMaterial({ vertexColors: true }));
  scene.add(terrainMesh);
}

/** 在粗糙度高的地方散佈岩塊（InstancedMesh），讓危險區看得出來。 */
function scatterRocks() {
  const g = S.rough, cell = S.meta.cell_m, picks = [];
  for (let j = 0; j < g.h; j += 2) for (let i = 0; i < g.w; i += 2) {
    const v = g.data[j * g.w + i];
    if (v > 40 && Math.random() < 0.35) picks.push([i, j, v]);
  }
  for (let k = 0; k < 2500; k++) picks.push([Math.random() * g.w, Math.random() * g.h, 8]); // 零星小石
  const geo = new THREE.DodecahedronGeometry(1, 0);
  const mesh = new THREE.InstancedMesh(geo, new THREE.MeshLambertMaterial({ color: '#6b3a24' }), picks.length);
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), e = new THREE.Euler();
  picks.forEach(([i, j, v], k) => {
    const x = (i + 0.5) * cell, y = (j + 0.5) * cell, s = 0.6 + (v / 254) * 5 * (0.5 + Math.random());
    e.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
    m.compose(groundV(x, y, s * 0.3), q.setFromEuler(e), new THREE.Vector3(s, s * 0.7, s));
    mesh.setMatrixAt(k, m);
  });
  scene.add(mesh);
}

const LAYER_STYLE = {
  slope: { ramp: ['#2e7d32', '#f2c94c', '#ff5a36', '#7a0c0c'], legend: ['0°', '22°', '45°'] },
  hazard: { ramp: ['#000000', '#ff2a2a'], alphaFromValue: true, legend: ['passable', 'no-go'] },
  cost: { ramp: ['#1b5e20', '#f2c94c', '#ff5a36', '#4a0000'], legend: ['cheap', 'expensive', '∞'] },
  coverage: { ramp: ['#ff3b30', '#f2c94c', '#3fd17a', '#2ec4ff'], legend: ['0 beacons', '1–2', '3+'] },
  pnr: { ramp: ['#ff3b30', '#3fd17a'], legend: ['beyond PNR', 'safe to reach & return'] },
};
function rampColor(ramp, t, out) {
  const n = ramp.length - 1, x = Math.min(Math.max(t, 0), 1) * n, i = Math.min(Math.floor(x), n - 1);
  return out.set(ramp[i]).lerp(new THREE.Color(ramp[i + 1]), x - i);
}
async function applyLayer() {
  const [kind, mode] = S.layer.split(':');
  const colors = terrainMesh.geometry.attributes.color;
  if (kind === 'none') {
    colors.array.set(baseColors);
    colors.needsUpdate = true;
    $('legend').style.background = 'none';
    $('legend-text').innerHTML = '';
    return;
  }
  const q = { step: MESH_STEP };
  if (kind === 'cost') q.mode = mode;
  if (kind === 'pnr') {
    const p = S.eva ? S.eva.est : { x: S.meta.base[0], y: S.meta.base[1] };
    Object.assign(q, { x: p.x, y: p.y, o2_min: S.eva ? S.eva.o2 : S.meta.params.o2_capacity_min });
  }
  const L = await api.layer(kind, q);
  const st = LAYER_STYLE[kind], { w, h } = S.terr, c = new THREE.Color(), base = new THREE.Color();
  for (let r = 0; r < h; r++) for (let col = 0; col < w; col++) {
    const k = r * w + col, v = L.data[(h - 1 - r) * w + col];
    base.fromArray(baseColors, k * 3);
    let a = 0.6, t;
    if (st.alphaFromValue) a = v > 127 ? 0.8 : 0;
    if (kind === 'coverage') t = Math.min((v / 254) * 6, 3) / 3; // 0..6 個信標 → 0..1（3 個以上算滿）
    else if (kind === 'pnr' || kind === 'hazard') t = v / 255;
    else t = v === 255 ? 1 : v / 254;
    rampColor(st.ramp, t, c);
    base.lerp(c, a);
    colors.setXYZ(k, base.r, base.g, base.b);
  }
  colors.needsUpdate = true;
  $('legend').style.background = `linear-gradient(90deg, ${st.ramp.join(',')})`;
  $('legend-text').innerHTML = st.legend.map((s) => `<span>${s}</span>`).join('');
}

