// ---------------------------------------------------------------- routes
const routeGroup = new THREE.Group();
scene.add(routeGroup);
function routeMesh(route, color) {
  const pts = [];
  for (let i = 0; i < route.path.length - 1; i++) {
    const [x0, y0] = route.path[i], [x1, y1] = route.path[i + 1];
    const n = Math.max(1, Math.ceil(Math.hypot(x1 - x0, y1 - y0) / 6));
    for (let s = 0; s < n; s++) pts.push(groundV(x0 + ((x1 - x0) * s) / n, y0 + ((y1 - y0) * s) / n, 1.5));
  }
  const last = route.path.at(-1);
  pts.push(groundV(last[0], last[1], 1.5));
  const mesh = new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), Math.min(pts.length * 2, 5000), 1.6, 6, false),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.95 }),
  );
  routeGroup.add(mesh);
  return mesh;
}
function clearRoutes() {
  routeGroup.children.slice().forEach((m) => { m.geometry.dispose(); routeGroup.remove(m); });
  S.routes = {};
}
function selectRoute(key) {
  S.selected = key;
  for (const [k, r] of Object.entries(S.routes)) r.mesh.material.opacity = k === key ? 1 : 0.25;
  document.querySelectorAll('.route-card').forEach((c) => c.classList.toggle('selected', c.dataset.key === key));
  $('start').disabled = !key || !!S.eva;
}
function card(key, r) {
  const div = document.createElement('div');
  div.className = 'route-card';
  div.dataset.key = key;
  div.style.setProperty('--c', COLORS[key]);
  if (!r) { div.innerHTML = `<h3>${key}</h3><div>No traversable route</div>`; return div; }
  div.innerHTML = `<h3>${key}</h3>
    <div class="stats">
      <span>Distance ${(r.length_m / 1000).toFixed(2)} km</span><span>ETA ${r.eta_min.toFixed(0)} min</span>
      <span>Max slope ${r.max_slope_deg.toFixed(0)}°</span><span>Clearance ${r.min_clearance_m.toFixed(0)} m</span>
      <span>Dose ${r.dose_msv.toFixed(3)} mSv</span><span>Risk ${(r.risk * 100).toFixed(0)}%</span>
    </div>
    <ul class="notes">${r.notes.map((n) => `<li>${n}</li>`).join('')}</ul>`;
  div.onclick = () => selectRoute(key);
  return div;
}
async function planRoutes() {
  if (S.eva) return;
  const t0 = performance.now();
  try {
    const res = await api.compare({ start: S.meta.base, goal: [S.goal.x, S.goal.y] });
    clearRoutes();
    $('routes').innerHTML = '';
    for (const key of ['safe', 'balanced', 'science']) {
      const r = res[key];
      if (r) S.routes[key] = { route: r, mesh: routeMesh(r, COLORS[key]) };
      $('routes').appendChild(card(key, r));
    }
    log(`3 routes planned on-board in ${(performance.now() - t0).toFixed(0)} ms`, 'ok');
    selectRoute(S.routes.safe ? 'safe' : Object.keys(S.routes)[0]);
  } catch (e) {
    log(`Planning failed: ${e.message}`, 'bad');
  }
}
function setActiveRoute(route, key) {
  clearRoutes();
  S.routes[key] = { route, mesh: routeMesh(route, COLORS[key] || COLORS.safe) };
  S.eva.route = route;
  S.eva.routeKey = key;
}

// ---------------------------------------------------------------- EVA (walkable)
const keys = new Set();
const keyName = (e) => ({ w: 'ArrowUp', s: 'ArrowDown', a: 'ArrowLeft', d: 'ArrowRight' })[e.key.toLowerCase()] || e.key;
addEventListener('keydown', (e) => {
  if (!S.eva) return;
  const k = keyName(e);
  if (k.startsWith('Arrow')) { keys.add(k); e.preventDefault(); }
});
addEventListener('keyup', (e) => keys.delete(keyName(e)));
document.querySelectorAll('#dpad button').forEach((b) => {
  b.addEventListener('pointerdown', (e) => { keys.add(b.dataset.k); e.preventDefault(); });
  ['pointerup', 'pointerleave', 'pointercancel'].forEach((ev) => b.addEventListener(ev, () => keys.delete(b.dataset.k)));
});

const feedback = new Feedback($('haptic'));
$('opt-sound').onchange = (e) => { feedback.sound = e.target.checked; feedback.unlockAudio(); };
$('opt-vibe').onchange = (e) => (feedback.vibrate = e.target.checked);

function startEva() {
  const r = S.routes[S.selected];
  if (!r) return;
  feedback.unlockAudio();
  const [bx, by] = S.meta.base;
  const first = r.route.path[Math.min(1, r.route.path.length - 1)];
  S.eva = {
    t: 0, o2: S.meta.params.o2_capacity_min, o2Rate: 1,
    pos: { x: bx, y: by }, heading: Math.atan2(first[1] - by, first[0] - bx),
    est: { x: bx, y: by }, sigma: 0.5, lastLocPos: { x: bx, y: by }, locTimer: 0, locBusy: false, seed: 1,
    route: r.route, routeKey: S.selected, mode: S.selected, nav: null, loc: null,
    drift: null, returning: false, done: false, replanning: false, lastReplan: 0,
  };
  astro.visible = estMarker.visible = true;
  scene.fog = FOG_EVA;
  $('hud').classList.remove('hidden');
  $('dpad').classList.remove('hidden');
  ['start', 'plan'].forEach((id) => ($(id).disabled = true));
  ['rockfall', 'leak', 'drift', 'home'].forEach((id) => ($(id).disabled = false));
  placeAstronaut();
  // 鏡頭切到太空人後方
  const p = astro.position;
  controls.target.copy(p);
  camera.position.set(p.x - Math.cos(S.eva.heading) * 60, p.y + 35, p.z + Math.sin(S.eva.heading) * 60);
  log(`EVA started on ${S.selected} route — ${$('autopilot').checked ? 'autopilot' : 'manual control (W/A/S/D)'}`, 'ok');
  showAlert(`EVA IN PROGRESS · ${S.selected.toUpperCase()} ROUTE`, true, 2500);
}

function placeAstronaut() {
  const e = S.eva;
  astro.position.copy(groundV(e.pos.x, e.pos.y, 0));
  astro.rotation.y = e.heading;
}

function walkSpeed(x, y) {
  // 與後端 eva.rs 相同的 Tobler 型速度模型（m/s），乘上時間倍率
  const v0 = S.meta.params.walk_speed_mps;
  return v0 * Math.exp(-3.5 * Math.tan((slopeAt(x, y) * Math.PI) / 180)) * TIME_SCALE;
}

function evaTick(dt) {
  const e = S.eva;
  if (!e || e.done) return;
  e.t += (dt * TIME_SCALE) / 60;
  e.o2 = Math.max(0, e.o2 - ((dt * TIME_SCALE) / 60) * e.o2Rate);

  // ---- 控制：自動駕駛（朝導引點）或鍵盤
  let turn = 0, fwd = 0;
  const paused = e.drift || performance.now() < (e.pauseUntil || 0); // 漂移後停下來重新定向
  if ($('autopilot').checked && e.nav && !e.replanning && !paused) {
    const want = Math.atan2(e.nav.next[1] - e.est.y, e.nav.next[0] - e.est.x);
    let d = want - e.heading;
    d = Math.atan2(Math.sin(d), Math.cos(d));
    turn = Math.max(-1, Math.min(1, d * 3));
    fwd = Math.abs(d) < 1.2 ? 1 : 0.2;
  }
  if (keys.has('ArrowLeft')) turn = 1;
  if (keys.has('ArrowRight')) turn = -1;
  if (keys.has('ArrowUp')) fwd = 1;
  if (keys.has('ArrowDown')) fwd = -0.5;
  e.heading += turn * 2.2 * dt;

  let blocked = false;
  if (fwd !== 0) {
    const v = walkSpeed(e.pos.x, e.pos.y) * fwd * dt;
    const nx = e.pos.x + Math.cos(e.heading) * v, ny = e.pos.y + Math.sin(e.heading) * v;
    if (isHazard(nx, ny)) blocked = true;
    else { e.pos.x = nx; e.pos.y = ny; }
  }
  // ---- 模擬漂移（例如鬆軟沙地滑移、導航錯誤）：1.2 秒內把真實位置推到側邊
  if (e.drift) {
    const k = Math.min(dt / Math.max(e.drift.left, 1e-3), 1);
    const nx = e.pos.x + e.drift.dx * k, ny = e.pos.y + e.drift.dy * k;
    if (!isHazard(nx, ny)) { e.pos.x = nx; e.pos.y = ny; }
    e.drift.dx -= e.drift.dx * k; e.drift.dy -= e.drift.dy * k; e.drift.left -= dt;
    if (e.drift.left <= 0) e.drift = null;
  }
  e.blocked = blocked;
  placeAstronaut();

  // ---- 鏡頭跟隨
  const delta = astro.position.clone().sub(controls.target);
  controls.target.add(delta);
  camera.position.add(delta);

  // ---- 定位（每 LOC_INTERVAL 秒一次；在 Worker 裡算，不卡畫面）
  e.locTimer += dt;
  if (e.locTimer > LOC_INTERVAL && !e.locBusy) {
    e.locTimer = 0;
    localizeAndTrack();
  }
  updateHud();

  // ---- 抵達判斷
  const end = e.route.path.at(-1);
  if (e.nav && e.nav.remaining_m < 8 && Math.hypot(e.pos.x - end[0], e.pos.y - end[1]) < 15) {
    e.done = true;
    ['rockfall', 'leak', 'drift', 'home'].forEach((id) => ($(id).disabled = true));
    if (e.returning) { log('Crew back at habitat. EVA complete.', 'ok'); showAlert('SAFE RETURN TO HABITAT', true, 5000); }
    else { log('Arrived at science target — begin sampling.', 'ok'); showAlert('TARGET REACHED · BEGIN SAMPLING', true, 5000); }
    feedback.update(performance.now(), { kind: 'none' });
  }
}

async function localizeAndTrack() {
  const e = S.eva;
  e.locBusy = true;
  try {
    const step = [e.pos.x - e.lastLocPos.x, e.pos.y - e.lastLocPos.y];
    e.lastLocPos = { ...e.pos };
    const loc = await api.localize({ true_pos: [e.pos.x, e.pos.y], prev_estimate: [e.est.x, e.est.y], prev_sigma: e.sigma, step_m: step, seed: e.seed++ });
    if (S.eva !== e) return;
    e.loc = loc;
    e.est = { x: loc.estimate[0], y: loc.estimate[1] };
    e.sigma = loc.sigma_m;
    drawLocalization(loc);
    if (e.replanning) return;
    const route = e.route;
    const nav = await api.track({ pos: [e.est.x, e.est.y], sigma_m: e.sigma, path: route.path, lookahead_m: 25 });
    if (S.eva !== e || e.done || e.route !== route) return;
    e.nav = nav;
    const now = performance.now();
    if (nav.status === 'replan' && !e.replanning && now - e.lastReplan > 2500) {
      log(`OFF ROUTE ${nav.xte_m.toFixed(0)} m (${nav.reason.replaceAll('_', ' ')}) → auto re-plan from estimated position`, 'warn');
      doReplan('Off route');
    } else if (nav.status === 'off_route' && e.lastStatus !== 'off_route') {
      log(`OFF ROUTE warning: ${nav.xte_m.toFixed(0)} m from the planned path`, 'warn');
    }
    e.lastStatus = nav.status;
  } catch (err) {
    if (err.code !== 'out_of_bounds') log(`Localization error: ${err.message}`, 'bad');
  } finally {
    e.locBusy = false;
  }
}

function drawLocalization(loc) {
  const e = S.eva;
  estMarker.position.copy(groundV(e.est.x, e.est.y, 0.6));
  estDot.position.y = 6;
  estRing.scale.setScalar(Math.max(loc.sigma_m, 1.5));
  estRing.material.color.set(loc.mode === 'multilateration' ? '#4dd6ff' : '#f2c94c');
  const pts = [];
  const me = groundV(e.est.x, e.est.y, 4);
  for (const b of loc.visible_beacons) if (beaconTop[b.id]) pts.push(beaconTop[b.id], me);
  beaconLines.geometry.dispose();
  beaconLines.geometry = new THREE.BufferGeometry().setFromPoints(pts);
}

function updateHud() {
  const e = S.eva, n = e.nav, loc = e.loc, reserve = S.meta.params.o2_reserve_min;
  $('g-time').textContent = `${e.t.toFixed(0)} min`;
  $('g-o2').textContent = `${e.o2.toFixed(0)} min`;
  if (loc) {
    $('g-pos').textContent = `± ${loc.sigma_m < 10 ? loc.sigma_m.toFixed(1) : loc.sigma_m.toFixed(0)} m`;
    $('g-bcn').textContent = `${loc.visible_beacons.length} · ${loc.mode === 'multilateration' ? 'multilat' : 'dead reck.'}`;
  }
  if (!n) return;
  const tRet = n.t_return_min;
  $('g-ret').textContent = Number.isFinite(tRet) ? `${tRet.toFixed(0)} min` : '—';
  const mustReturn = !e.returning && Number.isFinite(tRet) && e.o2 < tRet + reserve + 10;
  const clr = n.clearance_m;
  $('g-safe').textContent = e.blocked ? 'NO-GO ahead' : clr >= 20 ? 'safe' : clr >= 8 ? `caution ${clr.toFixed(0)} m` : `hazard ${clr.toFixed(0)} m`;
  $('g-safe').style.color = e.blocked || clr < 8 ? 'var(--bad)' : clr < 20 ? 'var(--warn)' : 'var(--ok)';

  // 狀態列 + 回饋
  const pill = $('status-pill');
  let kind = 'none';
  if (mustReturn) {
    pill.textContent = '⚠ RETURN TO BASE NOW — O₂ AT LIMIT'; pill.className = 'bad'; kind = 'return';
  } else if (e.replanning) {
    pill.textContent = 'RE-PLANNING ON-BOARD…'; pill.className = 'warn';
  } else if (e.blocked || clr < 5) {
    pill.textContent = e.blocked ? 'NO-GO TERRAIN AHEAD' : `HAZARD ${clr.toFixed(0)} m`; pill.className = 'bad'; kind = 'hazard';
  } else if (n.status !== 'on_route') {
    pill.textContent = `OFF ROUTE · ${n.xte_m.toFixed(0)} m`; pill.className = 'warn'; kind = 'offroute';
  } else {
    pill.textContent = e.returning ? 'RETURNING TO BASE · ON ROUTE' : 'ON ROUTE'; pill.className = '';
  }
  feedback.update(performance.now(), { kind, xte: n.xte_m, side: n.side });

  // 指引箭頭：導引點相對於太空人面向的方位
  const bearing = Math.atan2(n.next[1] - e.est.y, n.next[0] - e.est.x);
  let rel = bearing - e.heading;
  rel = Math.atan2(Math.sin(rel), Math.cos(rel));
  $('arrow').style.transform = `rotate(${(-rel * 180) / Math.PI}deg)`;
  const turnTxt = Math.abs(rel) < 0.2 ? 'straight ahead' : rel > 0 ? `turn left ${Math.round((rel * 180) / Math.PI)}°` : `turn right ${Math.round((-rel * 180) / Math.PI)}°`;
  $('compass-text').innerHTML = `${turnTxt}<br><small>${(n.remaining_m / 1000).toFixed(2)} km to ${e.returning ? 'base' : 'target'}</small>`;
}

async function doReplan(reasonText) {
  const e = S.eva;
  e.replanning = true;
  e.lastReplan = performance.now();
  const t0 = performance.now();
  try {
    const res = await api.replan({ pos: [e.est.x, e.est.y], goal: [S.goal.x, S.goal.y], mode: e.mode, obstacles: S.obstacles, o2_min: e.o2 });
    const ms = (performance.now() - t0).toFixed(0);
    if (S.eva !== e) return;
    if (res.must_return && res.return_route) {
      setActiveRoute(res.return_route, 'return');
      e.returning = true;
      const why = res.reason === 'goal_beyond_pnr' ? `round trip ${res.round_trip_min?.toFixed(0)} min exceeds O₂ budget` : 'no safe path to target';
      log(`${reasonText}: ${why} → RETURN TO BASE (computed on-board in ${ms} ms)`, 'bad');
      showAlert('BEYOND POINT OF NO RETURN · RETURN TO BASE', false, 5000);
      $('rockfall').disabled = true;
    } else if (res.route) {
      setActiveRoute(res.route, e.routeKey === 'return' ? 'safe' : e.routeKey);
      log(`${reasonText}: new route computed on-board in ${ms} ms (${res.route.eta_min.toFixed(0)} min to target)`, 'warn');
      showAlert('NEW ROUTE COMPUTED ON-BOARD', false, 3000);
    }
    e.nav = null;
    if (S.layer === 'pnr') applyLayer();
  } catch (err) {
    log(`Re-plan failed: ${err.message}`, 'bad');
  } finally {
    e.replanning = false;
  }
}

async function returnHome() {
  const e = S.eva;
  if (!e || e.returning) return;
  try {
    const r = await api.route({ start: [e.est.x, e.est.y], goal: S.meta.base, mode: 'safe' });
    setActiveRoute(r, 'return');
    e.returning = true;
    e.nav = null;
    log(`Return to base selected: ${(r.length_m / 1000).toFixed(2)} km, ${r.eta_min.toFixed(0)} min`, 'warn');
    showAlert('RETURNING TO BASE', true, 2500);
  } catch (err) {
    log(`Return route failed: ${err.message}`, 'bad');
  }
}

function pointAlong(path, d) {
  let acc = 0;
  for (let i = 1; i < path.length; i++) {
    const l = Math.hypot(path[i][0] - path[i - 1][0], path[i][1] - path[i - 1][1]);
    if (acc + l >= d) { const t = (d - acc) / (l || 1); return [path[i - 1][0] + (path[i][0] - path[i - 1][0]) * t, path[i - 1][1] + (path[i][1] - path[i - 1][1]) * t]; }
    acc += l;
  }
  return path.at(-1);
}
function rockfall() {
  const e = S.eva;
  if (!e || e.returning || !e.nav) return;
  if (e.nav.remaining_m < 120) return log('Too close to the target to place a rockfall', 'warn');
  const p = pointAlong(e.route.path, e.nav.along_m + Math.min(150, e.nav.remaining_m * 0.5));
  const o = { x: p[0], y: p[1], r: 30 };
  S.obstacles.push(o);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(o.r, o.r, 12, 24), new THREE.MeshBasicMaterial({ color: '#ff2a2a', transparent: true, opacity: 0.4 }));
  m.position.copy(groundV(o.x, o.y, 6));
  obstacleGroup.add(m);
  doReplan('Rockfall reported ahead');
}
function drift() {
  const e = S.eva;
  if (!e || !e.nav) return;
  // 往路線的垂直方向推 40 m（選不會撞進危險區的那一側）
  const a = pointAlong(e.route.path, e.nav.along_m), b = pointAlong(e.route.path, e.nav.along_m + 5);
  const len = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1;
  const nx = -(b[1] - a[1]) / len, ny = (b[0] - a[0]) / len;
  const side = isHazard(e.pos.x + nx * 45, e.pos.y + ny * 45) ? -1 : 1;
  e.drift = { dx: nx * 45 * side, dy: ny * 45 * side, left: 1.2 };
  e.pauseUntil = performance.now() + 3200;
  log('Simulated drift: crew pushed ~45 m sideways (true position) and stops to re-orient', 'warn');
}
function leak() {
  const e = S.eva;
  if (!e) return;
  e.o2 = Math.min(e.o2, 40);
  e.o2Rate = 3;
  $('leak').disabled = true;
  log('Suit O₂ leak detected: 40 min left, consumption ×3', 'bad');
  doReplan('O₂ leak');
}
function reset() {
  S.eva = null;
  S.obstacles = [];
  keys.clear();
  obstacleGroup.children.slice().forEach((m) => obstacleGroup.remove(m));
  astro.visible = estMarker.visible = false;
  beaconLines.geometry = new THREE.BufferGeometry();
  scene.fog = FOG_PLAN;
  clearRoutes();
  $('routes').innerHTML = '';
  $('hud').classList.add('hidden');
  $('dpad').classList.add('hidden');
  $('plan').disabled = false;
  ['start', 'rockfall', 'leak', 'drift', 'home'].forEach((id) => ($(id).disabled = true));
  overviewCamera();
  if (S.layer === 'pnr') applyLayer();
  log('Reset');
}

// ---------------------------------------------------------------- UI helpers
function log(msg, cls = '') {
  const div = document.createElement('div');
  div.className = cls;
  div.textContent = (S.eva ? `[T+${S.eva.t.toFixed(0)}] ` : '') + msg;
  $('log').prepend(div);
}
let alertTimer;
function showAlert(text, info, ms) {
  const a = $('alert');
  a.textContent = text;
  a.className = info ? 'info' : '';
  clearTimeout(alertTimer);
  alertTimer = setTimeout(() => a.classList.add('hidden'), ms);
}
function overviewCamera() {
  const shift = innerWidth > 700 ? -S.W * 0.16 : 0;
  camera.position.set(shift - S.W * 0.05, S.W * 0.78, S.H * 0.9);
  controls.target.set(shift, 0, -S.H * 0.04);
}

let down = null;
renderer.domElement.addEventListener('pointerdown', (e) => (down = [e.clientX, e.clientY]));
renderer.domElement.addEventListener('pointerup', (e) => {
  if (!down || Math.hypot(e.clientX - down[0], e.clientY - down[1]) > 5 || S.eva) return;
  const ray = new THREE.Raycaster();
  ray.setFromCamera(new THREE.Vector2((e.clientX / innerWidth) * 2 - 1, -(e.clientY / innerHeight) * 2 + 1), camera);
  const hit = ray.intersectObject(terrainMesh)[0];
  if (!hit) return;
  const p = fromV(hit.point);
  $('target').value = 'custom';
  $('target-desc').textContent = `Custom goal at (${p.x.toFixed(0)}, ${p.y.toFixed(0)}) m`;
  setGoal(p.x, p.y, `custom point (${p.x.toFixed(0)}, ${p.y.toFixed(0)}) m`);
});

// ---------------------------------------------------------------- boot
async function boot() {
  const t0 = performance.now();
  const { build_ms } = await api.ready();
  $('loading-text').textContent = 'Loading terrain…';
  S.meta = await api.meta();
  [S.terr, S.hazard, S.slope, S.rough] = await Promise.all([
    api.terrain(MESH_STEP), api.layer('hazard', { step: 1 }), api.layer('slope', { step: 1 }), api.layer('rough', { step: 1 }),
  ]);
  S.W = S.meta.width * S.meta.cell_m;
  S.H = S.meta.height * S.meta.cell_m;
  S.zmid = (S.meta.z_min + S.meta.z_max) / 2;
  buildTerrain();
  scatterRocks();
  addMarkers();
  overviewCamera();

  const sel = $('target');
  for (const t of S.meta.targets) sel.add(new Option(`${t.name} (science ${t.science})`, t.id));
  sel.add(new Option('Custom (click map)', 'custom'));
  const pick = () => {
    const t = S.meta.targets.find((x) => x.id === sel.value);
    if (!t) return;
    $('target-desc').textContent = t.desc;
    setGoal(t.x, t.y, t.name);
  };
  sel.onchange = pick;
  pick();

  $('layer').onchange = (e) => { S.layer = e.target.value; applyLayer().catch((err) => log(err.message, 'bad')); };
  $('plan').onclick = planRoutes;
  $('start').onclick = startEva;
  $('rockfall').onclick = rockfall;
  $('drift').onclick = drift;
  $('leak').onclick = leak;
  $('home').onclick = returnHome;
  $('reset').onclick = reset;
  const th = S.meta.thresholds;
  $('source').innerHTML = `Terrain: ${S.meta.source}<br>No-go thresholds: slope &gt; ${th.slope_max_deg.toFixed(0)}°, roughness &gt; ${th.rough_max_m.toFixed(2)} m.<br>`
    + `Engine: ${api.kind === 'wasm' ? 'WebAssembly in this browser' : 'local mars-server'} — no network link required.<br>Beacon ranges are simulated from the terrain model.`;
  $('loading').classList.add('done');
  log(`Loaded ${S.meta.name} (${S.meta.width}×${S.meta.height} @ ${S.meta.cell_m} m); engine ready in ${(build_ms || performance.now() - t0).toFixed(0)} ms`, 'ok');
}

const clock = new THREE.Clock();
renderer.setAnimationLoop(() => {
  const dt = Math.min(clock.getDelta(), 0.1);
  if (S.eva) evaTick(dt);
  controls.update();
  renderer.render(scene, camera);
  labels.render(scene, camera);
});
boot().catch((e) => { $('loading-text').textContent = `Failed to load: ${e.message}`; console.error(e); });

// e2e 測試用
window.__mm = { S, api };
